#!/usr/bin/env bash
# generated by team.sh — starts the 'architect' agent
export ATOMIC_ROLE=architect
export ATOMIC_INTERCOM_GROUP=harness
export BUILD_DIR=/Users/mp/git-repos/agentic-engineering-harness/build
export TEAMCHAT_FEED=/Users/mp/git-repos/agentic-engineering-harness/build/team-chat.log
cd "/Users/mp/git-repos/agentic-engineering-harness"
atomic -e /Users/mp/git-repos/agentic-engineering-harness/atomic/extensions/herdr-state.ts -e /Users/mp/git-repos/agentic-engineering-harness/atomic/extensions/intercom-bridge.ts --provider anthropic --model claude-sonnet-5 -n architect \
  --append-system-prompt "$(cat /Users/mp/git-repos/agentic-engineering-harness/team/architect.md)" \
  --append-system-prompt "$(cat /Users/mp/git-repos/agentic-engineering-harness/team/TRANSPORT.md)" \
  2> >(tee -a /Users/mp/git-repos/agentic-engineering-harness/build/.launch/architect.stderr.log >&2)
status=$?
echo; echo "[harness] the 'architect' session exited (status $status). Pane kept open."
echo "[harness] stderr: /Users/mp/git-repos/agentic-engineering-harness/build/.launch/architect.stderr.log"
echo "[harness] restart with: bash /Users/mp/git-repos/agentic-engineering-harness/build/.launch/architect.sh"
